import { useDispatch } from 'react-redux';
import { openSnackbar } from 'store/slices/snackbar';

const useSnackbar = () => {
    const dispatch = useDispatch();

    const showSnackbar = (message = '!No message Found', color = 'success') => {
        dispatch(
            openSnackbar({
                open: true,
                message,
                variant: 'alert',
                alert: {
                    color
                }
            })
        );
    };

    return { showSnackbar };
};

export default useSnackbar;
